/** Authored representative fixture; no observed commuter population. */
export function fireflyFixture(){return {schemaVersion:'population-snapshot.v1',modelVersion:'fixture.v1',runtime:{id:'fixture-run',revision:1},effectiveConfig:{seed:42},minute:1080,metrics:{activeTrips:1200},visibleAgents:Array.from({length:200},(_,i)=>({id:`fixture-p${String(i).padStart(3,'0')}`,weight:10,trip:{schemaVersion:'population-current-trip.v1',departureMinute:1070,durationMinutes:20,remainingMinutes:10,progress:.5,route:{kind:'mapped-sidewalk',rulesVersion:'sidewalks.v1',points:[[0,0],[10,0]],distanceMetres:10}}}))};}
